package com.innovatus.studentrecords.dao;
import com.innovatus.studentrecords.config.DBConnection; import com.innovatus.studentrecords.model.UploadHistory; import java.sql.*; import java.time.*; import java.util.*;
public class UploadHistoryDAO { public void create(int u,String f,String d,String b,String y,int n)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO upload_history(user_id,file_name,department,batch,year,total_records) VALUES(?,?,?,?,?,?)")){p.setInt(1,u);p.setString(2,f);p.setString(3,d);p.setString(4,b);p.setString(5,y);p.setInt(6,n);p.executeUpdate();}} public List<UploadHistory> recent(int u)throws SQLException{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM upload_history WHERE user_id=? ORDER BY upload_date DESC LIMIT 8")){p.setInt(1,u);try(ResultSet r=p.executeQuery()){List<UploadHistory> a=new ArrayList<>();while(r.next())a.add(new UploadHistory(r.getInt(1),u,r.getString("file_name"),r.getString("department"),r.getString("batch"),r.getString("year"),r.getInt("total_records"),r.getTimestamp("upload_date").toLocalDateTime()));return a;}}} }
